int main(int argc, char* argv[]) {
    // Verify the version of the library that we linked against is
    // compatible with the version of the headers we compiled against.
    GOOGLE_PROTOBUF_VERIFY_VERSION;

    if (argc != 3) {
        std::cerr << "Usage: " << argv[0] << " <input_problem.pb> <output_solution.pb>" << std::endl;
        return 1;
    }

    std::string problem_file_path = argv[1];
    std::string solution_file_path = argv[2];

    // Read the problem from the input file
    Problem problem_msg;
    std::fstream input(problem_file_path, std::ios::in | std::ios::binary);
    if (!input) {
        std::cerr << "Error: Could not open problem file: " << problem_file_path << std::endl;
        return 1;
    }
    
    std::cout << "C++ Planner: Successfully opened problem file" << std::endl;

    if (!problem_msg.ParseFromIstream(&input)) {
        std::cerr << "Error: Failed to parse problem from file: " << problem_file_path << std::endl;
        input.close();
        return 1;
    }
    input.close();

    std::cout << "C++ Planner: Successfully parsed problem message" << std::endl;

    // Solve the planning problem
    PlanGenerationResult result = solve_planning_problem(problem_msg);

    // Write the result to the output file
    std::fstream output(solution_file_path, std::ios::out | std::ios::trunc | std::ios::binary);
    if (!output) {
        std::cerr << "Error: Could not open output file: " << solution_file_path << std::endl;
        return 1;
    }

    if (!result.SerializeToOstream(&output)) {
        std::cerr << "Error: Failed to write result to file: " << solution_file_path << std::endl;
        output.close();
        return 1;
    }
    output.close();

    std::cout << "C++ Planner: Successfully wrote result to: " << solution_file_path << std::endl;

    // Optional: Delete all global objects allocated by libprotobuf.
    google::protobuf::ShutdownProtobufLibrary();

    return 0;
}